'use strict';

const fs = require('fs');
const input = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < input.length && input[pos] <= 32) pos++;
  let value = 0;
  while (pos < input.length && input[pos] > 32) {
    value = value * 10 + input[pos++] - 48;
  }
  return value;
}

const N = nextInt();
const M = nextInt();
const P = nextInt();

const rows = new Int32Array(N);
const cols = new Int32Array(M);

for (let i = 0; i < N; i++) rows[i] = i + 1;
for (let i = 0; i < M; i++) cols[i] = i + 1;

for (let i = 0; i < P; i++) {
  while (pos < input.length && input[pos] <= 32) pos++;
  const op = input[pos++];
  const a = nextInt() - 1;
  const b = nextInt() - 1;

  const perm = op === 76 ? rows : cols;
  const temp = perm[a];
  perm[a] = perm[b];
  perm[b] = temp;
}

const outputChunks = [];
let lineBatch = [];

for (let i = 0; i < N; i++) {
  const base = (rows[i] - 1) * M;
  const values = new Array(M);

  for (let j = 0; j < M; j++) {
    values[j] = base + cols[j];
  }

  lineBatch.push(values.join(' '));

  if (lineBatch.length === 1000) {
    outputChunks.push(lineBatch.join('\n'));
    lineBatch = [];
  }
}

if (lineBatch.length > 0) outputChunks.push(lineBatch.join('\n'));

process.stdout.write(outputChunks.join('\n'));
